const baseProducts = [
  { id: 1, name: 'Laptop', price: 999, inventory: 42, available: true },
  { id: 2, name: 'Phone', price: 699, inventory: 125, available: true },
  { id: 3, name: 'Tablet', price: 499, inventory: 0, available: false },
  { id: 4, name: 'Headphones', price: 199, inventory: 78, available: true },
  { id: 5, name: 'Watch', price: 299, inventory: 15, available: true },
]

let lastSyncTimestamp = null
let currentProducts = baseProducts.map((p) => ({ ...p }))

export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return {
    products: currentProducts,
    lastSynced: lastSyncTimestamp,
  }
}

export async function syncProductsFromERP() {
  await new Promise((resolve) => setTimeout(resolve, 2000))

  lastSyncTimestamp = new Date().toISOString()
  currentProducts = baseProducts.map((p) => ({
    ...p,
    price: p.price + Math.floor(Math.random() * 20 - 10),
    inventory: Math.max(0, p.inventory + Math.floor(Math.random() * 10 - 3)),
  }))

  return { syncedAt: lastSyncTimestamp }
}

