import { unstable_cache } from 'next/cache'
import { updateTag, revalidateTag } from 'next/cache'
import { after } from 'next/server'
import { getAllProducts, syncProductsFromERP } from '@/lib/db'

const getCachedProducts = unstable_cache(
  async () => getAllProducts(),
  ['products-cache-key'],
  { tags: ['products'] }
)

async function syncCatalog() {
  'use server'
  updateTag('products')
  after(async () => {
    await syncProductsFromERP()
    revalidateTag('products', { expire: 0 })
  })
}

export default async function AdminProductsPage() {
  const { products, lastSynced } = await getCachedProducts()

  return (
    <div>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      {lastSynced && (
        <p>
          Last synced: {new Date(lastSynced).toLocaleString()}
        </p>
      )}
      {!lastSynced && <p>Catalog has not been synced yet.</p>}

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
            <th>Inventory</th>
            <th>Available</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
              <td>{product.inventory}</td>
              <td>{product.available ? 'Yes' : 'No'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

